<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/research-workspace.php';require_once dirname(__DIR__).'/app/ai.php';require_once dirname(__DIR__).'/app/live.php';release_worker_heartbeat($pdo,'source_monitor','starting','Worker invocation started.');$releaseProcessed=0;$releaseFailed=0;
$limit=max(1,min(25,(int)($argv[1]??5)));
// Seed due watched/project sources without duplicating active jobs.
$pdo->exec("INSERT INTO source_monitor_jobs(source_id,priority,status) SELECT s.id,4,'queued' FROM sources s WHERE s.monitoring_enabled=1 AND (s.next_check_at IS NULL OR s.next_check_at<=NOW()) AND (EXISTS(SELECT 1 FROM source_watches sw WHERE sw.source_id=s.id) OR EXISTS(SELECT 1 FROM project_sources ps WHERE ps.source_id=s.id)) AND NOT EXISTS(SELECT 1 FROM source_monitor_jobs j WHERE j.source_id=s.id AND j.status IN ('queued','processing'))");
for($n=0;$n<$limit;$n++){
    $job=job_claim($pdo,'source_monitor_jobs',"SELECT j.*,s.public_id source_public_id,s.canonical_url,s.title source_title FROM source_monitor_jobs j JOIN sources s ON s.id=j.source_id WHERE j.status='queued' AND j.scheduled_at<=NOW() ORDER BY j.priority ASC,j.scheduled_at ASC,j.created_at ASC LIMIT 1",[],300);if(!$job)break;$id=(int)$job['id'];$token=(string)$job['claim_token'];$notification=null;$eventId=0;
    try{
        $fetch=fetch_public_url((string)$job['canonical_url']);$status=(int)$fetch['status'];job_claim_renew($pdo,'source_monitor_jobs',$id,$token,300);
        $parsed=$status>=200&&$status<400?html_to_research_text((string)$fetch['body']):['title'=>'','text'=>''];$text=(string)$parsed['text'];$title=$parsed['title']?:$job['source_title'];$hash=$text!==''?hash('sha256',normalize_match_text($text)):null;
        $pdo->beginTransaction();job_claim_assert($pdo,'source_monitor_jobs',$id,$token);$source=lock_source_row($pdo,(int)$job['source_id']);$current=source_current_version($pdo,$source);$currentId=(int)($source['current_version_id']??0);$wasUnavailable=((string)$source['status']==='unavailable');
        if($status<200||$status>=400){
            $sameUnavailable=false;if($current&&$source['status']==='unavailable'){$meta=json_decode((string)($current['metadata_json']??''),true);$sameUnavailable=(int)($meta['http_status']??0)===$status;}
            if($sameUnavailable){$pdo->prepare("UPDATE sources SET last_checked_at=NOW(),next_check_at=DATE_ADD(NOW(),INTERVAL 12 HOUR) WHERE id=?")->execute([$source['id']]);}
            else{$versionNo=next_source_version_number($pdo,(int)$source['id']);$q=$pdo->prepare('INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash,target_content_hash,metadata_json) VALUES(?,?,?,?,NULL,NULL,NULL,?)');$q->execute([$source['id'],$versionNo,$fetch['url'],$title,json_encode(['http_status'=>$status],JSON_UNESCAPED_SLASHES)]);$newId=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE sources SET current_version_id=?,status='unavailable',last_checked_at=NOW(),next_check_at=DATE_ADD(NOW(),INTERVAL 12 HOUR) WHERE id=?")->execute([$newId,$source['id']]);$pdo->prepare("INSERT INTO source_change_events(source_id,previous_version_id,new_version_id,change_type,target_changed,diff_summary) VALUES(?,?,?,'unavailable',0,?)")->execute([$source['id'],$currentId?:null,$newId,'Source returned HTTP '.$status.'.']);$eventId=(int)$pdo->lastInsertId();$notification='Source is currently unavailable.';}
        }elseif($current&&$hash!==null&&hash_equals((string)($current['content_hash']??''),$hash)){
            $pdo->prepare("UPDATE sources SET title=COALESCE(?,title),status='current',last_checked_at=NOW(),next_check_at=DATE_ADD(NOW(),INTERVAL 24 HOUR) WHERE id=?")->execute([$title?:null,$source['id']]);
        }else{
            $versionNo=next_source_version_number($pdo,(int)$source['id']);$pdo->prepare('INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash,target_content_hash,metadata_json) VALUES(?,?,?,?,?,?,?,?)')->execute([$source['id'],$versionNo,$fetch['url'],$title,$text,$hash,null,json_encode(['http_status'=>$status,'content_type'=>$fetch['content_type']],JSON_UNESCAPED_SLASHES)]);$newId=(int)$pdo->lastInsertId();
            $targetChanged=0;$q=$pdo->prepare("SELECT DISTINCT c.selected_text FROM captures c JOIN annotations a ON a.capture_id=c.id WHERE c.source_id=? AND a.status IN ('published','restricted') AND c.selected_text IS NOT NULL AND c.selected_text<>'' LIMIT 100");$q->execute([$source['id']]);$newNorm=normalize_match_text($text);foreach($q->fetchAll() as $r){$needle=normalize_match_text((string)$r['selected_text']);if($needle!==''&&!str_contains($newNorm,$needle)){$targetChanged=1;break;}}
            $type=$wasUnavailable?'restored':($targetChanged?'edited':'updated');$oldText=(string)($current['extracted_text']??'');$diff=simple_text_diff($oldText,$text,120);$added=0;$removed=0;$sample=[];foreach($diff as $d){if($d['type']==='added')$added++;elseif($d['type']==='removed')$removed++;if($d['type']!=='same'&&count($sample)<4&&trim($d['text'])!=='')$sample[]=($d['type']==='added'?'+ ':'- ').mb_substr(trim($d['text']),0,180);}$summary="Detected $added added and $removed removed lines.".($sample?' '.implode(' | ',$sample):'');
            $pdo->prepare('UPDATE sources SET title=?,current_version_id=?,status=?,last_checked_at=NOW(),next_check_at=DATE_ADD(NOW(),INTERVAL 24 HOUR) WHERE id=?')->execute([$title,$newId,$wasUnavailable?'current':$type,$source['id']]);$pdo->prepare('INSERT INTO source_change_events(source_id,previous_version_id,new_version_id,change_type,target_changed,diff_summary) VALUES(?,?,?,?,?,?)')->execute([$source['id'],$currentId?:null,$newId,$type,$targetChanged,$summary]);$eventId=(int)$pdo->lastInsertId();$notification=$wasUnavailable?'Source restored.':($targetChanged?'Referenced passage changed after capture.':'A monitored source changed.');
        }
        if($eventId){source_integrity_analyze_event($pdo,$eventId);source_integrity_notify_event($pdo,$eventId);live_event_emit_source_change($pdo,(int)$job['source_id'],$eventId);}
        job_claim_complete($pdo,'source_monitor_jobs',$id,$token);$pdo->commit();
        if($eventId&&research_workspace_ready($pdo)){$pq=$pdo->prepare('SELECT project_id FROM project_sources WHERE source_id=?');$pq->execute([$job['source_id']]);foreach($pq->fetchAll(PDO::FETCH_COLUMN) as $projectId)research_workspace_queue($pdo,(int)$projectId,3);}
        if($eventId&&function_exists('research_monitor_queue_for_source'))research_monitor_queue_for_source($pdo,(int)$job['source_id'],'source_change');
        if($eventId){try{$model=ai_setting_model_id($pdo,'source_monitor');if($model)ai_queue_job($pdo,null,'source_change_summary',$model,'source_change_event',(string)$eventId,[],3);}catch(Throwable $e){}}
        $releaseProcessed++;echo "source job {$job['id']} done\n";
    }catch(LostJobClaim $e){if($pdo->inTransaction())$pdo->rollBack();$releaseFailed++;fwrite(STDERR,"source job {$job['id']}: lease lost; stale fetch discarded\n");}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();try{job_claim_retry_or_fail($pdo,'source_monitor_jobs',$id,$token,substr($e->getMessage(),0,1000),(int)$job['attempts'],3,1800);}catch(LostJobClaim $lost){}$releaseFailed++;fwrite(STDERR,"source job {$job['id']}: {$e->getMessage()}\n");}
}
release_worker_heartbeat($pdo,'source_monitor',$releaseFailed?'failure':'success',$releaseFailed?("$releaseFailed source job(s) failed; $releaseProcessed completed."):("$releaseProcessed source job(s) completed."),$releaseProcessed);
function notify_source_dependents(PDO $pdo,int $sourceId,string $body): void {
    $q=$pdo->prepare('SELECT DISTINCT user_id FROM source_watches WHERE source_id=? UNION SELECT DISTINCT rp.owner_user_id FROM project_sources ps JOIN research_projects rp ON rp.id=ps.project_id WHERE ps.source_id=?');$q->execute([$sourceId,$sourceId]);$q2=$pdo->prepare('SELECT public_id FROM sources WHERE id=?');$q2->execute([$sourceId]);$sourcePublic=(string)$q2->fetchColumn();foreach($q->fetchAll(PDO::FETCH_COLUMN) as $uid)notify_user($pdo,(int)$uid,null,'source_changed','source',$sourcePublic,$body);
}
